// Everything the mod logs also goes to a short in-memory list, shown on the
// settings window's About page so it can be read and copied without
// Windhawk's log window.
std::mutex g_logMutex;
[[clang::no_destroy]] std::deque<std::wstring> g_logLines;
// How many recent lines the About page keeps (about 150 KB at most).
constexpr size_t kLogHistoryLines = 1000;

void ModLog(const wchar_t* format, ...) {
    wchar_t buffer[1024];
    va_list args;
    va_start(args, format);
    int written = _vsnwprintf(buffer, std::size(buffer) - 1, format, args);
    va_end(args);
    buffer[std::size(buffer) - 1] = 0;
    if (written < 0) buffer[std::size(buffer) - 2] = 0;
    Wh_Log(L"%s", buffer);
    SYSTEMTIME now{};
    GetLocalTime(&now);
    wchar_t stamp[20];
    swprintf_s(stamp, L"%02u:%02u:%02u.%03u ", now.wHour, now.wMinute,
               now.wSecond, now.wMilliseconds);
    std::lock_guard lock(g_logMutex);
    g_logLines.push_back(std::wstring(stamp) + buffer);
    while (g_logLines.size() > kLogHistoryLines) g_logLines.pop_front();
}

// ---- Diagnostic logs ---------------------------------------------------
// About ▸ Troubleshooting: "Advanced logs" is the master switch (on by
// default); under it, one switch per area (all on by default). While on, an
// area writes what happens in it to the Windhawk log (and the About page's
// list), event by event, never once per frame, at most 600 lines per area
// per minute (a flood is cut and counted, then the area carries on, so a
// session of days keeps logging). The master off turns every area off at
// once and hides their
// switches until it is on again.
enum DiagArea {
    kDiagReadings,  // The Readings page's swell and clicks.
    kDiagDetails,   // The details panel: opening, closing, switching.
    kDiagTaskbar,   // Where the widgets are placed on the taskbar.
    kDiagData,      // Requests to the internet, speed tests.
    kDiagSettings,  // The settings window: pages, redraws, popups.
    kDiagSystem,    // The mod's own health: handles, objects, uptime.
    kDiagLifecycle, // Start, settings reloads, shutdown.
    kDiagCount
};
constexpr int kDiagMaxPerWindow = 600;        // Lines per area per window.
constexpr ULONGLONG kDiagWindowMs = 60000;    // The window: one minute.
constexpr PCWSTR kDiagKeys[kDiagCount] = {
    L"ui.log.readings", L"ui.log.details", L"ui.log.taskbar", L"ui.log.data",
    L"ui.log.settings", L"ui.log.system", L"ui.log.lifecycle"};
constexpr PCWSTR kDiagNames[kDiagCount] = {L"Readings", L"Details",
                                           L"Taskbar",  L"Data",
                                           L"Settings", L"System",
                                           L"Lifecycle"};
std::atomic<bool> g_diagOn[kDiagCount];
std::atomic<bool> g_diagMaster{true};  // Advanced logs: the master switch.
// Troubleshooting ▸ "Panel: fixed top while resizing" (on by default): see
// ApplyHoverPlace. Off: the window's top moves with the card, as before.
std::atomic<bool> g_panelFixedTop{true};
std::atomic<int> g_diagLines[kDiagCount];  // Lines asked for, all session.
struct DiagWindow {
    ULONGLONG start = 0;
    int count = 0;    // Written in this window.
    int dropped = 0;  // Left out in this window.
};
std::mutex g_diagRateMutex;
DiagWindow g_diagWindow[kDiagCount];

bool DiagOn(int area) {
    return area >= 0 && area < kDiagCount &&
           g_diagMaster.load(std::memory_order_relaxed) &&
           g_diagOn[area].load(std::memory_order_relaxed);
}
void DiagLog(int area, const wchar_t* format, ...) {
    if (!DiagOn(area)) return;
    ++g_diagLines[area];
    int leftOutBefore = 0;
    bool firstLeftOut = false;
    bool allowed = true;
    {
        ULONGLONG now = GetTickCount64();
        std::lock_guard lock(g_diagRateMutex);
        DiagWindow& w = g_diagWindow[area];
        if (now - w.start >= kDiagWindowMs) {
            leftOutBefore = w.dropped;
            w.start = now;
            w.count = 0;
            w.dropped = 0;
        }
        if (w.count >= kDiagMaxPerWindow) {
            firstLeftOut = (++w.dropped == 1);
            allowed = false;
        } else {
            ++w.count;
        }
    }
    if (leftOutBefore > 0) {
        ModLog(L"[%s] %d lines were left out in the last minute (limit %d "
               L"a minute)",
               kDiagNames[area], leftOutBefore, kDiagMaxPerWindow);
    }
    if (firstLeftOut) {
        ModLog(L"[%s] more than %d lines in a minute: the rest are left out "
               L"until the minute ends",
               kDiagNames[area], kDiagMaxPerWindow);
    }
    if (!allowed) return;
    wchar_t buffer[900];
    va_list args;
    va_start(args, format);
    _vsnwprintf(buffer, std::size(buffer) - 1, format, args);
    va_end(args);
    buffer[std::size(buffer) - 1] = 0;
    ModLog(L"[%s] %s", kDiagNames[area], buffer);
}

std::wstring ModLogText() {
    std::lock_guard lock(g_logMutex);
    std::wstring text;
    for (const auto& line : g_logLines) text += line + L"\r\n";
    return text;
}

// Explorer's private memory in bytes (0 if unavailable). Handles, GDI and
// USER counts miss plain heap growth, so the System log shows this too.
// Same layout as PROCESS_MEMORY_COUNTERS_EX; kernel32 exports the call as
// K32GetProcessMemoryInfo, which avoids linking psapi.
unsigned long long ExplorerPrivateBytes() {
    struct MemoryCountersLocal {
        DWORD cb;
        DWORD PageFaultCount;
        SIZE_T PeakWorkingSetSize;
        SIZE_T WorkingSetSize;
        SIZE_T QuotaPeakPagedPoolUsage;
        SIZE_T QuotaPagedPoolUsage;
        SIZE_T QuotaPeakNonPagedPoolUsage;
        SIZE_T QuotaNonPagedPoolUsage;
        SIZE_T PagefileUsage;
        SIZE_T PeakPagefileUsage;
        SIZE_T PrivateUsage;
    };
    using GetInfoFn = BOOL(WINAPI*)(HANDLE, void*, DWORD);
    static GetInfoFn getInfo = []() -> GetInfoFn {
        HMODULE kernel = GetModuleHandleW(L"kernel32.dll");
        if (!kernel) return nullptr;
        return reinterpret_cast<GetInfoFn>(
            reinterpret_cast<void*>(GetProcAddress(kernel,
                                                   "K32GetProcessMemoryInfo")));
    }();
    if (!getInfo) return 0;
    MemoryCountersLocal counters{};
    counters.cb = sizeof(counters);
    if (!getInfo(GetCurrentProcess(), &counters, sizeof(counters))) return 0;
    return counters.PrivateUsage;
}

