struct MetricsSnapshot {
    SampleTime capturedAt{};
    // Items read only for the details panel in this sample (not due on their
    // own period). The taskbar must not redraw them from such a sample.
    std::array<bool, kItemCount> detailsOnly{};
    double cpu = 0.0;
    bool cpuAvailable = false;
    double ram = 0.0;
    double ramUsedGb = 0.0;
    double ramTotalGb = 0.0;
    bool ramAvailable = false;
    double gpu = 0.0;
    bool gpuAvailable = false;
    double vram = 0.0;
    double vramUsedGb = 0.0;
    double vramTotalGb = 0.0;
    bool vramAvailable = false;
    // Data used today and this month, in bytes, down and up.
    double usageDayDown = 0, usageDayUp = 0;
    double usageMonthDown = 0, usageMonthUp = 0;
    // The same on metered connections only (Windows' Metered connection
    // switch, set per network: a phone's hotspot, say).
    double meteredDayDown = 0, meteredDayUp = 0;
    double meteredMonthDown = 0, meteredMonthUp = 0;
    bool meteredNow = false;   // The internet connection now is metered.
    std::wstring networkNow;   // Its name (Wi-Fi name, or the adapter's).
    struct NetworkDay {
        std::wstring name;
        double down = 0, up = 0;
        bool metered = false;
    };
    std::vector<NetworkDay> usageByNetwork;  // Today, per network.
    bool usageAvailable = false;
    // The connection carrying internet traffic.
    std::wstring connectionType;  // "Wi-Fi 7", "Ethernet"; empty if none.
    std::wstring connectionName;  // Wi-Fi network name or adapter name.
    // The access point's own hardware address ("AA:BB:CC:DD:EE:FF"), empty
    // off Wi-Fi. Unlike connectionName (the SSID, which a person can
    // rename any time in their router), this stays the same for as long as
    // it is the same physical router, so it is what identifies "the same
    // network" across a rename for matching speed-test history.
    std::wstring connectionBssid;
    std::wstring connectionBand;  // "2.4 GHz", "5 GHz", "6 GHz".
    double connectionMbps = 0;    // Link speed.
    int connectionSignal = -1;    // Wi-Fi signal quality, 0-100.
    bool connectionWifi = false;
    double netDownBytes = 0.0;  // Per second.
    double netUpBytes = 0.0;
    bool netAvailable = false;
    std::optional<double> cpuTemp;
    std::optional<double> gpuTemp;
    TemperatureProvider cpuTempProvider = TemperatureProvider::None;
    TemperatureProvider gpuTempProvider = TemperatureProvider::None;
    // HWiNFO power readings in watts.
    std::optional<double> cpuPowerW, gpuPowerW;
    // Whole-machine draw: battery discharge on battery, else CPU + discrete GPU.
    std::optional<double> totalPowerW;
    double pingMs = -2.0;  // Round trip in ms; -1 no answer, -2 not yet.
    // Fixed adapters: [0] integrated, [1] discrete.
    struct GpuSlotReading {
        double usage = 0.0;
        bool usageAvailable = false;
        double mem = 0.0, memUsedGb = 0.0, memTotalGb = 0.0;
        bool memAvailable = false;
        std::optional<double> temp;
        std::optional<double> powerW;
    };
    std::array<GpuSlotReading, 2> gpuSlots{};
    // A hybrid laptop's discrete GPU with no activity for 30 seconds: the
    // system has normally powered it down, and nothing is asked of it (a
    // question would wake it). Its readings are then drawn as idle, not as
    // missing.
    bool dgpuAsleep = false;
    // Adapter names for [auto] labels: plain gpu, integrated, discrete.
    std::array<std::wstring, 3> gpuNames;
    // Battery. Rate is positive while charging, negative while discharging.
    std::optional<double> batteryPercent;
    bool batteryCharging = false;
    bool batteryOnAc = false;
    std::optional<double> batteryRateW;
    std::optional<double> batteryRemainingWh, batteryFullWh, batteryDesignWh;
    std::optional<double> batterySecondsLeft;  // To empty or to full.
    // All disks together: bytes per second and active time, %.
    double diskRead = 0, diskWrite = 0, diskActive = 0;
    bool diskAvailable = false;
    // Each physical disk: Windows' name ("0 C:", "1 D: E:"), same values.
    struct DiskSample {
        std::wstring name;
        double read = 0, write = 0, active = 0;
    };
    std::vector<DiskSample> disks;
    // Fans from HWiNFO or an ASUS laptop: name, RPM.
    std::vector<std::pair<std::wstring, double>> fans;
};

// Ping: measured by its own thread (a lost packet takes a second or more),
// the metrics worker only reads the last answer.
std::atomic<double> g_pingMs{-2.0};  // -1 no answer, -2 not measured yet.

// How good a round trip is: 0 green (under 50 ms), 1 yellow (50 to 99),
// 2 orange (100 to 149), 3 red (150 and up). One scale for the widget, the
// tray icon and the speed test.
int PingLevel(double ms) {
    if (ms >= 150) return 3;
    if (ms >= 100) return 2;
    if (ms >= 50) return 1;
    return 0;
}
// Dark-background colors; the light variants are darker for contrast.
constexpr uint8_t kPingRgb[4][3] = {{0x2E, 0xC2, 0x6E},
                                    {0xE8, 0xC8, 0x1C},
                                    {0xE8, 0x9A, 0x1C},
                                    {0xE5, 0x4D, 0x4D}};
constexpr uint8_t kPingRgbLight[4][3] = {{0x10, 0x7C, 0x10},
                                         {0x9D, 0x7A, 0x00},
                                         {0xCA, 0x50, 0x10},
                                         {0xC4, 0x2B, 0x1C}};
// The ping as text: "34 ms", "<1 ms", "Offline" (no answer), "--" (not yet).
std::wstring PingText(double ms) {
    if (ms <= -1.5) return L"--";
    if (ms < 0) return L"Offline";
    if (ms < 1) return L"<1 ms";
    return std::to_wstring(static_cast<int>(std::lround(ms))) + L" ms";
}
// What a round trip means in use, as a rule of thumb.
std::wstring PingVerdict(double ms) {
    if (ms <= -1.5) return L"Measuring...";
    if (ms < 0) {
        return L"No answer. The connection may be down, or this network "
               L"blocks ping.";
    }
    switch (PingLevel(ms)) {
        case 0: return L"Fast. Calls, games and browsing feel instant.";
        case 1:
            return L"Good. Browsing and calls are fine; fast games can feel a "
                   L"little delayed.";
        case 2:
            return L"Slow. Pages and calls work, but games lag and calls may "
                   L"stutter.";
        default:
            return L"Poor. Expect visible lag in games, calls and remote "
                   L"desktop.";
    }
}
constexpr const wchar_t* kPingRanges[4] = {L"Under 50 ms", L"50 to 99 ms",
                                           L"100 to 149 ms",
                                           L"150 ms and up"};
constexpr const wchar_t* kPingNames[4] = {L"Fast", L"Good", L"Slow", L"Poor"};
// The band a reading is in, for highlighting it: -1 while not measured.
int PingBand(double ms) {
    if (ms <= -1.5) return -1;
    return ms < 0 ? 3 : PingLevel(ms);
}

