// Kept only when the backup is restored (see RestoreSettingsIfFresh).
constexpr KeptSetting kPageSettings[] = {{L"readingsSource", false, L"menu"},
                                         {L"items", false, L""}};
// Storage the mod writes itself: taskbar menu set-up and dragged positions.
constexpr PCWSTR kKeptStorage[] = {L"menu.items", L"menu.layout",
                                   L"menu.presetApplied", L"placement.v1"};

const KeptSetting* FindKept(PCWSTR name) {
    for (const auto& s : kKeptSettings) {
        if (wcscmp(s.key, name) == 0) return &s;
    }
    return nullptr;
}

// Choices made in the mod's settings window are kept as overrides in its
// storage: "ui.<setting>" = "=" + value, and "ui.base.<setting>" = "=" + the
// Windhawk value at that moment. The last change wins: while the Windhawk
// page still holds that same value the override applies; once the page
// changes the setting, the page's value becomes the kept value. This is
// for the few settings still on the page (kPageSettings); the rest live in
// the mod's storage only (kKeptSettings). A copy of everything goes to a
// file outside Windhawk (BackupSettings) so a reinstall brings it back.
std::wstring ReadStored(const std::wstring& key, size_t capacity = 4096) {
    std::vector<wchar_t> buffer(capacity);
    Wh_GetStringValue(key.c_str(), buffer.data(), buffer.size());
    return buffer.data();
}

std::wstring ApplyUiOverride(PCWSTR name, const std::wstring& windhawk) {
    std::wstring key = std::wstring(L"ui.") + name;
    std::wstring value = ReadStored(key);
    if (value.empty() || value[0] != L'=') return windhawk;
    std::wstring baseKey = std::wstring(L"ui.base.") + name;
    if (ReadStored(baseKey) != L"=" + windhawk) {
        Wh_SetStringValue(key.c_str(), (L"=" + windhawk).c_str());
        Wh_SetStringValue(baseKey.c_str(), (L"=" + windhawk).c_str());
        return windhawk;
    }
    return value.substr(1);
}

std::wstring WindhawkStringSetting(PCWSTR name) {
    return WindhawkUtils::StringSetting::make(name).get();
}

// A setting kept only by the mod: its stored value, else the default.
std::wstring KeptValue(const KeptSetting& s) {
    std::wstring value = ReadStored(std::wstring(L"ui.") + s.key);
    if (!value.empty() && value[0] == L'=') return value.substr(1);
    return s.fallback;
}

std::wstring GetStringSetting(PCWSTR name) {
    if (const KeptSetting* kept = FindKept(name)) return KeptValue(*kept);
    return ApplyUiOverride(name, WindhawkStringSetting(name));
}

int GetIntSetting(PCWSTR name) {
    if (const KeptSetting* kept = FindKept(name)) {
        return _wtoi(KeptValue(*kept).c_str());
    }
    std::wstring value =
        ApplyUiOverride(name, std::to_wstring(Wh_GetIntSetting(name)));
    return _wtoi(value.c_str());
}

void SetUiOverride(PCWSTR name, const std::wstring& value, bool isInt) {
    if (FindKept(name)) {
        Wh_SetStringValue((std::wstring(L"ui.") + name).c_str(),
                          (L"=" + value).c_str());
        return;
    }
    std::wstring windhawk = isInt ? std::to_wstring(Wh_GetIntSetting(name))
                                  : WindhawkStringSetting(name);
    Wh_SetStringValue((std::wstring(L"ui.base.") + name).c_str(),
                      (L"=" + windhawk).c_str());
    Wh_SetStringValue((std::wstring(L"ui.") + name).c_str(),
                      (L"=" + value).c_str());
}

void ClearUiOverride(PCWSTR name) {
    Wh_SetStringValue((std::wstring(L"ui.") + name).c_str(), L"");
    Wh_SetStringValue((std::wstring(L"ui.base.") + name).c_str(), L"");
}

std::wstring WindhawkValue(const KeptSetting& s) {
    return s.isInt ? std::to_wstring(Wh_GetIntSetting(s.key))
                   : WindhawkStringSetting(s.key);
}

// Undoes the settings window: every setting back to its default, and
// Choose readings with and Items back to the Windhawk page's values.
void ResetUiChanges() {
    for (const auto& s : kKeptSettings) ClearUiOverride(s.key);
    for (const auto& s : kPageSettings) ClearUiOverride(s.key);
}

// The Windhawk page's reset switch acts when it turns on.
// The Windhawk page's switches act when flipped, either way: true once
// per flip. The first look only records the position.
bool SwitchFlipped(PCWSTR setting, PCWSTR seenKey) {
    std::wstring now = Wh_GetIntSetting(setting) ? L"1" : L"0";
    std::wstring seen = ReadStored(seenKey);
    Wh_SetStringValue(seenKey, now.c_str());
    return !seen.empty() && seen != now;
}

void HandleResetSwitch() {
    if (SwitchFlipped(L"resetSettings", L"reset.seen2")) {
        ResetUiChanges();
        ModLog(L"Settings window changes reset");
    }
}

// Readings came from the Items setting when Choose readings with was Items
// text (older versions). Once, that text becomes the window's set-up.
void MigrateReadingsSource() {
    if (ReadStored(L"readings.v2") == L"1") return;
    Wh_SetStringValue(L"readings.v2", L"1");
    if (GetStringSetting(L"readingsSource") != L"items") return;
    std::wstring legacy = GetStringSetting(L"items");
    if (!legacy.empty()) Wh_SetStringValue(L"menu.items", legacy.c_str());
}

std::wstring ReadStoredLong(PCWSTR key) {
    std::vector<wchar_t> buffer(32768);
    size_t length = Wh_GetStringValue(key, buffer.data(), buffer.size());
    if (length == 0 || length >= buffer.size()) return {};
    return buffer.data();
}

// %APPDATA%\Taskbar System Monitor: outside Windhawk, so removing and
// reinstalling the mod keeps it.
std::wstring BackupFolder() {
    // FOLDERID_RoamingAppData.
    static constexpr GUID kRoamingAppData = {
        0x3EB685DB, 0x65F9, 0x4CF6,
        {0xA0, 0x3A, 0xE3, 0xEF, 0x65, 0x72, 0x9F, 0x3D}};
    PWSTR known = nullptr;
    std::wstring folder;
    if (SUCCEEDED(SHGetKnownFolderPath(kRoamingAppData, 0, nullptr,
                                       &known)) &&
        known) {
        folder = std::wstring(known) + L"\\Taskbar System Monitor";
    }
    CoTaskMemFree(known);
    return folder;
}

std::wstring EscapeBackup(const std::wstring& text) {
    std::wstring out;
    for (wchar_t ch : text) {
        if (ch == L'\\') out += L"\\\\";
        else if (ch == L'\n') out += L"\\n";
        else if (ch == L'\r') out += L"\\r";
        else if (ch == L'\t') out += L"\\t";
        else out += ch;
    }
    return out;
}

std::wstring UnescapeBackup(const std::wstring& text) {
    std::wstring out;
    for (size_t i = 0; i < text.size(); ++i) {
        if (text[i] != L'\\' || i + 1 == text.size()) {
            out += text[i];
            continue;
        }
        wchar_t next = text[++i];
        out += next == L'n' ? L'\n' : next == L'r' ? L'\r'
             : next == L't' ? L'\t' : next;
    }
    return out;
}

[[clang::no_destroy]] std::mutex g_backupMutex;

void BackupSettings() {
    std::lock_guard lock(g_backupMutex);
    std::wstring folder = BackupFolder();
    if (folder.empty()) return;
    std::wstring text = L"Taskbar System Monitor settings, v1\n";
    auto add = [&](PCWSTR kind, PCWSTR key, const std::wstring& value) {
        text += std::wstring(kind) + L"\t" + key + L"\t" +
                EscapeBackup(value) + L"\n";
    };
    for (const auto& s : kKeptSettings) {
        add(L"set", s.key,
            s.isInt ? std::to_wstring(GetIntSetting(s.key))
                    : GetStringSetting(s.key));
    }
    for (const auto& s : kPageSettings) {
        add(L"set", s.key, GetStringSetting(s.key));
    }
    for (PCWSTR key : kKeptStorage) {
        std::wstring value = ReadStoredLong(key);
        if (!value.empty()) add(L"raw", key, value);
    }
    std::string utf8 = ToUtf8(text);
    CreateDirectoryW(folder.c_str(), nullptr);
    std::wstring path = folder + L"\\settings.txt";
    std::wstring temp = path + L".new";
    HANDLE file = CreateFileW(temp.c_str(), GENERIC_WRITE, 0, nullptr,
                              CREATE_ALWAYS, FILE_ATTRIBUTE_NORMAL, nullptr);
    if (file == INVALID_HANDLE_VALUE) {
        ModLog(L"Settings backup: cannot write %s", temp.c_str());
        return;
    }
    DWORD written = 0;
    BOOL ok = WriteFile(file, utf8.data(), static_cast<DWORD>(utf8.size()),
                        &written, nullptr);
    CloseHandle(file);
    if (!ok || written != utf8.size() ||
        !MoveFileExW(temp.c_str(), path.c_str(), MOVEFILE_REPLACE_EXISTING)) {
        DeleteFileW(temp.c_str());
        ModLog(L"Settings backup failed");
    }
}

// After a fresh install (empty storage) the backup file, if any, brings
// the earlier choices back.
void RestoreSettingsIfFresh() {
    if (!ReadStored(L"storage.v1").empty()) return;
    Wh_SetStringValue(L"storage.v1", L"1");
    for (const auto& s : kKeptSettings) {
        if (!ReadStored(std::wstring(L"ui.") + s.key).empty()) return;
    }
    for (PCWSTR key : kKeptStorage) {
        if (!ReadStoredLong(key).empty()) return;
    }
    std::wstring folder = BackupFolder();
    if (folder.empty()) return;
    HANDLE file = CreateFileW((folder + L"\\settings.txt").c_str(),
                              GENERIC_READ, FILE_SHARE_READ, nullptr,
                              OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, nullptr);
    if (file == INVALID_HANDLE_VALUE) return;
    std::string utf8;
    char chunk[4096];
    DWORD read = 0;
    while (ReadFile(file, chunk, sizeof(chunk), &read, nullptr) && read > 0) {
        utf8.append(chunk, read);
        if (utf8.size() > 1024 * 1024) break;
    }
    CloseHandle(file);
    std::wstring text = Utf8ToWide(utf8);
    if (text.empty()) return;
    auto findKept = [](const std::wstring& key) -> const KeptSetting* {
        for (const auto& s : kKeptSettings) {
            if (key == s.key) return &s;
        }
        for (const auto& s : kPageSettings) {
            if (key == s.key) return &s;
        }
        return nullptr;
    };
    int restored = 0;
    for (std::wstring& line : SplitText(text, L'\n')) {
        size_t tab1 = line.find(L'\t');
        size_t tab2 = tab1 == std::wstring::npos ? tab1
                                                  : line.find(L'\t', tab1 + 1);
        if (tab2 == std::wstring::npos) continue;
        std::wstring kind = line.substr(0, tab1);
        std::wstring key = line.substr(tab1 + 1, tab2 - tab1 - 1);
        std::wstring value = UnescapeBackup(line.substr(tab2 + 1));
        if (kind == L"set") {
            if (const KeptSetting* s = findKept(key)) {
                if (FindKept(s->key) || WindhawkValue(*s) != value) {
                    SetUiOverride(s->key, value, s->isInt);
                }
                ++restored;
            }
        } else if (kind == L"raw") {
            for (PCWSTR allowed : kKeptStorage) {
                if (key == allowed) {
                    Wh_SetStringValue(allowed, value.c_str());
                    ++restored;
                }
            }
        }
    }
    ModLog(L"Restored %d settings from %s", restored, folder.c_str());
}

// Runs before settings load: the backup after a reinstall, then the
// Windhawk page's reset switch.
void PrepareSettingsStorage() {
    RestoreSettingsIfFresh();
    MigrateReadingsSource();
    HandleResetSwitch();
    SwitchFlipped(L"openSettings", L"open.seen");  // Records it; no window.
}

