PCWSTR ReadingName(int item) {
    return item >= 0 && item < kItemCount ? kItemNames[item].full : L"Reading";
}

constexpr PCWSTR kMenuTag = L"WindhawkTaskbarSystemMonitorMenu";



// The settings page (and section) about a kind of reading, for the taskbar
// menu: right-clicking the weather offers Weather settings.
struct UiTopic {
    int id = -1;  // Index in kUiTopics; -1: none.
    PCWSTR menu = L"";
};
struct UiTopicPlace {
    PCWSTR menu, page, section;
};
// A reading with a section of its own goes straight to that section, not
// to the top of its page (Ping lands on Ping, not on Network's speeds).
// The indices are used by name (kUiTopic...), so new places go at the end.
constexpr UiTopicPlace kUiTopics[] = {
    {L"Network settings", L"Network", L"Speeds"},
    {L"Weather settings", L"Weather", nullptr},
    {L"Exchange rate settings", L"Exchange rate", nullptr},
    {L"Battery settings", L"Battery", nullptr},
    {L"Sensor settings", L"Sensors", nullptr},
    {L"Ping settings", L"Network", L"Ping"},
    {L"Battery settings", L"Battery", L"Time and health"},
};
static_assert(std::size(kUiTopics) == kUiTopicBatteryTime + 1,
              "kUiTopics and its kUiTopic... indices must match");

UiTopic TopicOfItem(int item) {
    int id = -1;
    switch (item) {
        case kItemDown: case kItemUp: case kItemNet: case kItemUsage:
        case kItemUsageMonth: case kItemConnection:
            id = kUiTopicNetwork;
            break;
        case kItemPing: id = kUiTopicPing; break;
        case kItemWeather: id = kUiTopicWeather; break;
        case kItemCurrency: id = kUiTopicCurrency; break;
        case kItemBattery: case kItemBatteryPower:
            id = kUiTopicBattery;
            break;
        case kItemBatteryTime: case kItemBatteryHealth:
            id = kUiTopicBatteryTime;
            break;
        case kItemFan: id = kUiTopicSensors; break;
        default:
            switch (GpuKindOf(item)) {
                case kItemCpuTemp: case kItemGpuTemp: case kItemCpuPower:
                case kItemGpuPower: case kItemTotalPower:
                    id = kUiTopicSensors;
                    break;
                default:
                    break;
            }
    }
    if (id < 0) return {};
    return {id, kUiTopics[id].menu};
}

// The taskbar menu's entries. On a reading: its kind's settings (when it has
// a page, such as Network settings), then the settings window with the
// reading picked on its Readings page. Elsewhere: the settings window.
std::vector<MenuFlyoutItemBase> BuildMonitorMenu(std::optional<int> entry) {
    std::vector<MenuFlyoutItemBase> result;
    auto add = [&](const std::wstring& text, wchar_t glyph, int topic) {
        MenuFlyoutItem item;
        item.Text(text);
        item.Tag(winrt::box_value(winrt::hstring(kMenuTag)));
        FontIcon icon;
        icon.Glyph(std::wstring(1, glyph));
        item.Icon(icon);
        item.Click([entry, topic](IInspectable const&, RoutedEventArgs const&) {
            if (g_unloading) return;
            try {
                OpenSettingsWindow(topic >= 0 ? std::nullopt : entry, topic);
            } catch (...) {
            }
        });
        result.push_back(item);
    };
    if (entry) {
        UiTopic topic = TopicOfItem(CurrentSettings()->ItemOf(*entry));
        if (topic.id >= 0) add(topic.menu, 0xE713, topic.id);  // Settings.
    }
    add(L"System Monitor settings", 0xE9D9, -1);  // Diagnostic.
    return result;
}

// ===========================================================================
// BLOCK D: SETTINGS GUI WINDOW
// ===========================================================================
// The settings window, its pages and the drag-and-drop readings editor.

// ---------------------------------------------------------------------------
// Settings window
// ---------------------------------------------------------------------------
// A Windows 11 style window (XAML in a desktop window) for the settings most
// people change, opened from the taskbar menu: System Monitor settings.
// It runs on a thread of its own, created when it opens and ended when it
// closes, so the taskbar never waits for it and nothing is left behind.
// Choices are stored as overrides (see UiOverride) and applied at once.

namespace xhosting = winrt::Windows::UI::Xaml::Hosting;

