    PCWSTR key;
    UiKind kind;
    PCWSTR title;
    PCWSTR description;
    std::vector<UiOption> options{};
    int minimum = 0, maximum = 100, step = 1;
    PCWSTR unit = L"";
    // Shown dimmed unless this other setting has this value.
    PCWSTR needsKey = nullptr, needsValue = nullptr, needsLabel = nullptr;
