// The sidebar: every page is its own entry, so any setting is one click
// away. Entries come in a few runs (the taskbar's look, the details panel,
// where data comes from, About), stacked flush like Windows Settings.
// childNames is kept for a group entry that opens a list of pages instead
// (none now).
struct UiTopEntry {
    PCWSTR name;
    wchar_t glyph;
    std::vector<PCWSTR> childNames;
};

const std::vector<UiTopEntry>& UiTopEntries() {
    static const std::vector<UiTopEntry> entries = {
        {L"Readings", 0xE9D9, {}},
        {L"Look", 0xE771, {}},
        {L"Position", 0xE7F4, {}},
        {L"Battery", 0xE83F, {}},
        {L"Details panel", 0xE8A1, {}},
        {L"Network", 0xE701, {}},
        {L"Weather", 0xE753, {}},
        {L"Exchange rate", 0xE8C7, {}},
        {L"Sensors", 0xE950, {}},
        {L"Privacy", 0xE72E, {}},
        {L"About", 0xE946, {}},
    };
    return entries;
}

// The UiPages() index of a top entry's child, by name (-1: not found).
int UiPageIndexByName(PCWSTR name) {
    const auto& pages = UiPages();
    for (size_t i = 0; i < pages.size(); i++) {
        if (wcscmp(pages[i].name, name) == 0) return static_cast<int>(i);
    }
    return -1;
}

// The top entry a UiPages() page belongs to, whether it is itself a top
// entry (Readings, About) or one of a group's pages (Appearance, Behavior,
// Data).
int UiTopEntryForPage(int page) {
    const auto& pages = UiPages();
    if (page < 0 || page >= static_cast<int>(pages.size())) return 0;
    PCWSTR name = pages[page].name;
    const auto& tops = UiTopEntries();
    for (size_t i = 0; i < tops.size(); i++) {
        if (tops[i].childNames.empty()) {
            if (wcscmp(tops[i].name, name) == 0) return static_cast<int>(i);
        } else {
            for (PCWSTR child : tops[i].childNames) {
                if (wcscmp(child, name) == 0) return static_cast<int>(i);
            }
        }
    }
    return 0;
}

// The value the window shows: an override, else the Windhawk setting.
std::wstring UiValue(const UiSetting& s) {
    return UiIsInt(s.kind) ? std::to_wstring(GetIntSetting(s.key))
                           : GetStringSetting(s.key);
}

std::wstring UiValueOf(PCWSTR key) {
    for (const auto& page : UiPages()) {
        for (const auto& section : page.sections) {
            for (const auto& s : section.settings) {
                if (wcscmp(s.key, key) == 0) return UiValue(s);
            }
        }
    }
    return GetStringSetting(key);
}

// Keeps the window's choice and applies it: the taskbar reloads its
// settings (marshaled to its own thread by ReloadAllSettings).
void UiAfterCommit(PCWSTR key);  // After g_ui, below.

void UiCommit(const UiSetting& s, const std::wstring& value) {
    SetUiOverride(s.key, value, UiIsInt(s.kind));
    ReloadAllSettings();
    UiAfterCommit(s.key);
}

using UiZone = ModSettings::ZoneKind;
// The Readings page's preview (see BuildReadingsPreview).
struct UiToken {  // A reading (entry >= 0) or divider drawn in a zone.
    Border element{nullptr};
    UiZone slot = UiZone::Left;
    int cell = 0;
    int entry = -1;
};
struct UiBlockArea {  // One drawn block of a zone and its first cell.
    FrameworkElement element{nullptr};
    UiZone slot = UiZone::Left;
    int firstCell = 0;
};
struct UiSlotArea {
    UiZone kind = UiZone::Left;
    Border area{nullptr};
    Button add{nullptr};  // Its + button, the anchor of its panel.
    // Folded, a row with readings shows their count instead of them.
    FrameworkElement drawing{nullptr};
    TextBlock summary{nullptr};
    bool open = true;
    bool gliding = false;  // Its height is on the move (UiRowFrame).
    double target = 0;     // The height it is gliding to.
    bool resume = false;   // Redrawn mid-change: glides on from where it was.
    bool empty = false;    // No readings: always slim.
    FrameworkElement art{nullptr};  // The readings as drawn, at full size.
};
// A group of joined readings picked by a click on its edge (Delete removes it).
struct UiPickedGroup {
    UiZone slot = UiZone::Left;
    int cell = 0;
    int count = 1;
};
struct UiDrag {
    bool active = false;
    bool moving = false;
    Point start{};
    std::wstring name;
    // The source: a reading of a zone, or a divider of a zone.
    int fromEntry = -1;
    UiZone fromSlot = UiZone::Left;
    int fromCell = -1;
    // A whole group of joined readings (one or two cells of a block) moves
    // at once: dragged by the block's edge, or with Shift held on a reading.
    bool wholeCell = false;
    int cellCount = 1;
    int cellMembers = 0;  // Readings in the cell a reading belongs to.
    // A new reading dragged out of the + panel (kItemCount: a divider);
    // -1: the drag moves something already in a zone.
    int newItem = -1;
    std::wstring newPick;
    // Its size as drawn, for the ghost that shows where it would land.
    double width = 60, height = 22;
    // The target: a zone, before a cell (-1: at the end), or a reading to
    // join, before or after it (left/right, centre), or stacked one line
    // each above or below it (top/bottom).
    bool targetValid = false;
    UiZone target = UiZone::Left;
    int targetCell = -1;
    int joinEntry = -1;
    bool joinBefore = false;
    bool stack = false;
    // The last move's choice (reading and side), held a little longer so
    // the target does not flicker between two choices on a boundary.
    int lastMagnet = -1;
    int lastSide = 2;  // Centre.
    bool lastJoinBefore = false;
};
constexpr double kUiContentMaxDefault = 1000;

// The live preview above every page: each zone's widget as it looks on
// the taskbar, in taskbar order, each in a faint box of its own with the
// zone's name at the top. Built from the same pieces a taskbar copy on another
// monitor uses and refreshed once a second.
struct UiPreviewZone {
    Border frame{nullptr};       // A faint box around the whole zone.
    StackPanel column{nullptr};  // In it: the zone's name over its widget.
    Grid root{nullptr};
    std::optional<WidgetElements> view;
    std::optional<WidgetLayout> layout;
    double width = 0, height = 0;  // The widget's box as last applied.
    uint64_t revision = 0;  // The settings it was last styled for.
    bool light = false;
};
struct UiLivePreview {
    StackPanel column{nullptr};  // The bar, then the no-room notice.
    Border bar{nullptr};
    Viewbox fit{nullptr};
    StackPanel strip{nullptr};
    TextBlock note{nullptr};
    // Under the bar: whose colors it is drawn in (the taskbar's, which can
    // be dark while this window is light).
    TextBlock themeNote{nullptr};
    // By ModSettings::ZoneKind; made when a zone first has readings.
    std::array<UiPreviewZone, 9> zones;
    std::vector<int> shown;  // The kinds in the strip, left to right.
    std::array<SolidColorBrush, 2> alertBrushes{nullptr, nullptr};
    SolidColorBrush textBrush{nullptr};
    DispatcherTimer timer{nullptr};
};

struct UiWindowState {
    StackPanel content{nullptr};
    // Above the scrolling part: the Readings page's title, top bar and text
    // box in Text view, so only the reference below them scrolls.
    StackPanel head{nullptr};
    Border headHost{nullptr};
    Grid root{nullptr};        // The whole window's content.
    double contentWidth = kUiContentMaxDefault;  // As fitted to the window.
    // The page list folds to its icons in a narrow window, like Windows
    // Settings.
    ColumnDefinition navColumn{nullptr};
    std::vector<TextBlock> navTexts;
    // Set while the content area shows a group's drill-down list (its
    // UiTopEntries() index) instead of one of its pages; the sidebar still
    // highlights that top entry either way (see ShowUiGroupList,
    // UiTopEntryForPage). Null when a real page (UiPages()) is showing.
    std::optional<int> groupList;
    // True while ShowUiPage/ShowUiGroupList are themselves setting the
    // sidebar's SelectedIndex to match what's showing, so the
    // SelectionChanged handler knows to ignore that change rather than
    // treating it as a fresh click and re-dispatching.
    bool navSyncing = false;
    StackPanel historyButtons{nullptr};
    Grid side{nullptr};
    bool compact = false, fitted = false;
    Grid pageGrid{nullptr};    // Head, scrolling part, dock.
    std::set<std::wstring> changedKeys;  // Settings off their default, as drawn.
    // Battery page: redraws the small batteries of Level colors, and keeps
    // that editor's state alive while the page shows.
    std::function<void()> batteryPreview;
    std::shared_ptr<void> batteryEditor;
    ScrollViewer scroller{nullptr};
    ListView nav{nullptr};
    int page = 0;
    bool light = false;
    DispatcherTimer debounce{nullptr};
    std::function<void()> pending;
    // Readings page.
    int pickedEntry = -1;
    std::optional<std::pair<UiZone, int>> pickedDivider;  // Zone, cell.
    std::optional<UiPickedGroup> pickedGroup;
    std::optional<UiZone> focusZone;    // Where clicked capsules go.
    // A click on empty page takes the focus off every row (focusZone then
    // only says where an added reading would go).
    bool focusNone = false;
    UIElement previewRoot{nullptr};
    XamlRectangle dropMarker{nullptr};
    Border joinHint{nullptr};
    // Its own outline color, given back when the hint goes.
    winrt::Windows::UI::Xaml::Media::Brush joinHintBrush{nullptr};
    winrt::Windows::UI::Xaml::Media::Brush joinHintFill{nullptr};
    Border ghost{nullptr};
    TextBlock ghostText{nullptr};
    // Where the dragged reading would land if let go now: a faint dashed
    // copy of it at that place.
    Grid dropGhost{nullptr};
    TextBlock dropGhostText{nullptr};
    // A capsule of the + panel pressed and maybe about to be dragged out.
    struct PanelPress {
        bool active = false;
        Point start{};  // In the window's own coordinates.
        int item = -1;
        std::wstring pick, name;
    } panelPress;
    ULONGLONG panelDragEnd = 0;  // A drag from the panel just ended.
    // The reading just dropped: it settles in with a short animation.
    int flashEntry = -1;
    std::vector<UiToken> tokens;
    std::vector<UiBlockArea> blocks;
    std::vector<UiSlotArea> slots;
    UiDrag drag;
    // Rows unfold for the zone in focus, the one under the pointer and,
    // while dragging, the one dragged over.
    std::optional<UiZone> dragOver;
    // The row the pointer is on, kept here (not on the row) so the shade
    // survives a redraw of the page and a press on the row.
    std::optional<UiZone> hoverZone;
    // The options panel: where on the page it was opened.
    Point optionsAt{0, 0};
    // What the open options are about (see UiShowOptions): the same
    // reading, divider or group keeps them where they were opened.
    long long optionsSubject = 0;
    StackPanel zonesPanel{nullptr};  // The rows' own panel.
    DispatcherTimer rowTimer{nullptr};
    DispatcherTimer devicesTimer{nullptr};  // Joins redraws for new devices.
    // Whether each row (by zone) is drawn unfolded, kept across redraws of
    // the page so a row that changes state glides instead of being rebuilt
    // in its new shape; unknown when the page is entered.
    std::array<bool, 9> rowOpen{};
    bool rowKnown = false;
    // Each row's height as last shown and its speed, kept across redraws
    // so a redraw in the middle of a change does not cut the glide.
    struct RowGlide {
        double h = 0, foldH = 0, openH = 0;
        // This glide: ms passed on the screen's frame clock, its length.
        double from = 0, elapsed = 0, dur = 0;
        int64_t lastFrame = 0;  // 100 ns units; 0 before the first frame.
        double artH = 0;  // The readings' own height, kept while it moves.
        bool active = false;
    };
    std::array<RowGlide, 9> rowGlide{};
    // Settings pages with the keyboard: the card it is on.
    int cardPick = -1;
    bool cardNav = false;
    Border cardLit{nullptr};
    HyperlinkButton pageReset{nullptr};
    TextBlock missingLine{nullptr};  // "Not available on this PC right now".
    // A group's list of pages, for the keyboard (Up, Down, Enter).
    std::vector<Border> groupRows;
    std::vector<int> groupPages;
    int groupPick = -1;
    std::vector<int> suggestions;
    Flyout options{nullptr};
    ScrollViewer optionsScroll{nullptr};
    double optionsOffset = 0;
    bool optionsOpen = false;
    bool reopenOptions = false;
    bool narrow = false;  // The page is narrow: the Readings rows stack.
    // A line under the Readings page's top bar ("Applied Full."), and what
    // Undo puts back: the readings, the default style and look settings
    // as stored before (empty: not set).
    std::wstring notice;
    struct Undo {
        std::wstring items, layout;
        std::vector<std::pair<std::wstring, std::wstring>> stored;
    };
    std::optional<Undo> undo;
    Flyout adder{nullptr};  // The + panel of a zone, while it is open.
    // The arrow keys were used on the zones: the focused zone's + shows
    // a ring, and Delete may clear the zone. A click ends it.
    bool keyNav = false;
    // Search: the box above the page list and what is typed in it. While
    // it is not empty the content area shows the matching settings.
    TextBox searchBox{nullptr};
    std::wstring search;
    UiLivePreview preview;             // The strip above every page.
    Flyout presets{nullptr};
    bool presetsOpen = false;  // The Presets panel is showing right now.
    // The Presets panel stays open while presets are tried: it is drawn
    // again under the button once the page is rebuilt.
    bool reopenPresets = false;
    ULONGLONG presetsKeepUntil = 0;  // A choice was just made: keep the panel.
    double presetsOffset = 0;
    FrameworkElement presetsAnchor{nullptr};
    std::wstring scrollSection;  // A heading to scroll to once shown.
    // Undo, redo and history at the foot of the page list.
    DispatcherTimer historyTimer{nullptr};
    // Readings page: says when the taskbar is too full (see ZoneFit).
    TextBlock fitNotice{nullptr};
    Button undoButton{nullptr}, redoButton{nullptr}, historyButton{nullptr};
    Button privacyButton{nullptr};  // Quick toggle of privacyModeMaster.
    TextBlock privacyAutoStatus{nullptr};  // Privacy page: what was detected.
    TextBlock historyNote{nullptr};
};
