// Points the sidebar's highlight at a top entry without that, in turn,
// re-triggering SelectionChanged's own page/group dispatch (guarded by
// navSyncing, which that handler checks and bails out on).
void UiSyncNavSelection(int topEntry) {
    if (!g_ui.nav) return;
    bool was = g_ui.navSyncing;
    g_ui.navSyncing = true;
    try {
        if (g_ui.nav.SelectedIndex() != topEntry) {
            g_ui.nav.SelectedIndex(topEntry);
        }
    } catch (...) {
    }
    g_ui.navSyncing = was;
}

